#pragma once

#include <scratchcpp/value_functions.h>
#include <scratchcpp/string_functions.h>
#include <scratchcpp/string_pool.h>
#include <scratchcpp/stringptr.h>
#include <scratchcpp/executioncontext.h>
#include <scratchcpp/irandomgenerator.h>
#include <scratchcpp/iengine.h>
#include <scratchcpp/target.h>
#include <scratchcpp/stage.h>
#include <scratchcpp/list.h>
#include <utf8.h>
#include <cmath>
#include <cstdint>
#include <cstring>
#include <iostream>
#include <limits>
#include <numbers>

#include "cppexecutablecode.h"
#include "cppcompilercontext.h"
#include "cppexecutioncontext.h"

namespace libscratchcpp::cpp
{

static constexpr double PI = std::numbers::pi;

struct Str
{
        Str() :
            s(string_pool_new())
        {
            // Pooled strings may contain old data
            string_assign_cstring(s, "");
        }

        Str(const char *str) :
            s(string_pool_new())
        {
            string_assign_cstring(s, str);
        }

        Str(const Str &) = delete;
        ~Str() { string_pool_free(s); }

        void reset(StringPtr *str)
        {
            string_pool_free(s);
            s = str;
        }

        StringPtr *s;
};

struct Val
{
        Val() { value_init(&v); }
        Val(const Val &) = delete;
        ~Val() { value_free(&v); }

        void reset(const ValueData &data)
        {
            value_free(&v);
            v = data;
        }

        ValueData v;
};

// Procedure arguments
template<size_t N>
struct Args
{
        Args()
        {
            for (ValueData &value : v)
                value_init(&value);
        }

        Args(const Args &) = delete;

        ~Args()
        {
            for (ValueData &value : v)
                value_free(&value);
        }

        ValueData v[N > 0 ? N : 1];
};

inline double num(double v)
{
    return std::isnan(v) ? 0 : v;
}

inline double num(bool v)
{
    return v;
}

inline double num(const StringPtr *v)
{
    return value_stringToDouble(v);
}

inline double num(const ValueData &v)
{
    return value_toDouble(&v);
}

inline bool boolean(double v)
{
    return v != 0 && !std::isnan(v);
}

inline bool boolean(bool v)
{
    return v;
}

inline bool boolean(const StringPtr *v)
{
    return value_stringToBool(v);
}

inline bool boolean(const ValueData &v)
{
    return value_toBool(&v);
}

inline void str(StringPtr *dst, double v)
{
    value_doubleToStringPtr(v, dst);
}

inline void str(StringPtr *dst, bool v)
{
    string_assign_cstring(dst, v ? "true" : "false");
}

inline void str(StringPtr *dst, const StringPtr *v)
{
    string_assign(dst, v);
}

inline void str(StringPtr *dst, const ValueData &v)
{
    value_toStringPtr(&v, dst);
}

inline void val(ValueData *dst, double v)
{
    value_assign_double(dst, v);
}

inline void val(ValueData *dst, bool v)
{
    value_assign_bool(dst, v);
}

inline void val(ValueData *dst, const StringPtr *v)
{
    value_assign_stringPtr(dst, v);
}

inline void val(ValueData *dst, const ValueData &v)
{
    value_assign_copy(dst, &v);
}

inline double mod(double a, double b)
{
    double r = std::fmod(a, b);
    return (r / b < 0.0) ? r + b : r;
}

inline double round(double x)
{
    return x >= 0.0 ? std::round(x) : (x >= -0.5 ? -0.0 : std::floor(x + 0.5));
}

inline double sin(double x)
{
    return std::round(std::sin(x * PI / 180.0) * 1e10) / 1e10 + 0.0;
}

inline double cos(double x)
{
    return std::round(std::cos(x * PI / 180.0) * 1e10) / 1e10;
}

inline double tan(double x)
{
    double m = std::fmod(x, 360.0);

    if (m == -270.0 || m == 90.0)
        return std::numeric_limits<double>::infinity();
    else if (m == -90.0 || m == 270.0)
        return -std::numeric_limits<double>::infinity();

    return std::round(std::tan(x * PI / 180.0) * 1e10) / 1e10 + 0.0;
}

inline double randomValue(ExecutionContext *ctx, const ValueData *from, const ValueData *to)
{
    return value_isInt(from) && value_isInt(to) ? ctx->rng()->randint(value_toLong(from), value_toLong(to)) : ctx->rng()->randintDouble(value_toDouble(from), value_toDouble(to));
}

inline double randomInt(ExecutionContext *ctx, double from, double to)
{
    return ctx->rng()->randint((int64_t)from, (int64_t)to);
}

inline void print(const StringPtr *string)
{
    std::cout << utf8::utf16to8(std::u16string(string->data, string->size));
}

inline double random(ExecutionContext *ctx, double from, double to)
{
    double sum = from + to;

    if (std::isinf(sum) || std::isnan(sum))
        return sum;

    ValueData a, b;
    value_init(&a);
    value_init(&b);
    value_assign_double(&a, from);
    value_assign_double(&b, to);
    double ret = randomValue(ctx, &a, &b);
    value_free(&a);
    value_free(&b);
    return ret;
}

inline double random(ExecutionContext *ctx, const ValueData &from, const ValueData &to)
{
    double sum = value_toDouble(&from) + value_toDouble(&to);

    if (std::isinf(sum) || std::isnan(sum))
        return sum;

    return randomValue(ctx, &from, &to);
}

inline void concat(StringPtr *dst, const StringPtr *a, const StringPtr *b)
{
    size_t size = a->size + b->size;
    string_alloc(dst, size);
    std::memmove(dst->data, a->data, a->size * sizeof(char16_t));
    std::memmove(dst->data + a->size, b->data, b->size * sizeof(char16_t));
    dst->data[size] = 0;
    dst->size = size;
}

inline void stringChar(StringPtr *dst, const StringPtr *s, double index)
{
    string_alloc(dst, 1);
    bool inRange = index >= 0 && index < s->size;
    dst->data[0] = inRange ? s->data[(size_t)index] : 0;
    dst->data[1] = 0;
    dst->size = inRange ? 1 : 0;
}

inline bool listIndexInRange(List *list, double index, bool allowEnd = false)
{
    return index >= 0 && (allowEnd ? index <= list->size() : index < list->size());
}

inline void listItem(ValueData *dst, List *list, double index)
{
    if (listIndexInRange(list, index))
        value_assign_copy(dst, &(*list)[(size_t)index]);
    else
        value_assign_cstring(dst, "");
}

inline double listIndexOf(List *list, const ValueData &item)
{
    size_t index = list->indexOf(item);
    return index == (size_t)-1 ? -1.0 : (double)index;
}

inline Stage *stage(ExecutionContext *ctx)
{
    return ctx->engine()->stage();
}

} // namespace libscratchcpp::cpp
